export function validateHouseState(model){const state=model.houses;if(state===undefined)return;check(state?.schemaVersion===HOUSE_VERSION&&state.homes&&state.active&&typeof state.homes==='object'&&typeof state.active==='object'&&!Array.isArray(state.homes)&&!Array.isArray(state.active),'Unsupported or invalid optional house state');check(Object.keys(state.homes).length<=128&&Object.keys(state.active).length<=32,'Interior state exceeds retention bounds');for(const [key,house]of Object.entries(state.homes)){const h=householdIndex(model,Number(key));validateHouseProgression(house,model);validateHouseholdPets(house);if(house.floorTiles!==undefined){check(house.floorTiles&&typeof house.floorTiles==='object'&&!Array.isArray(house.floorTiles)&&Object.keys(house.floorTiles).length<=4096,'Invalid saved floor squares');for(const [key,tile] of Object.entries(house.floorTiles)){validateFlooring(tile.roomId,tile.style);validateFloorTile({x:tile.x,z:tile.z});check(key===floorTileKey(tile.roomId,tile),'Invalid floor square identity');}}if(house.flooring!==undefined){check(house.flooring&&typeof house.flooring==='object'&&!Array.isArray(house.flooring),'Invalid saved flooring');for(const [roomId,style] of Object.entries(house.flooring))validateFlooring(roomId,style);}if(house.wallLayout!==undefined){check(house.wallLayout.schemaVersion===HOUSE_WALL_VERSION,'Unknown wall layout version');normalizeHouseWalls(house.wallLayout.walls);}check(String(h)===key&&house.schemaVersion===HOUSE_VERSION&&house.householdId===`${model.prefix}-h${h}`,'Invalid interior household identity');check(Array.isArray(house.rooms)&&[4,5,6].includes(house.rooms.length)&&new Set(house.rooms.map(r=>r.id)).size===house.rooms.length&&house.rooms.every(r=>['bedroom','kitchen','living','study','garden','bathroom'].includes(r.id)&&['noise','light','privacy','cleanliness'].every(k=>Number.isFinite(r[k])&&r[k]>=0&&r[k]<=1)),'Invalid interior room state');check(Number.isSafeInteger(house.nextAction)&&house.nextAction>=0&&house.totals&&Object.values(house.totals).every(v=>Number.isFinite(v)&&v>=0)&&Array.isArray(house.objects)&&house.objects.length<=64&&Array.isArray(house.actions)&&house.actions.length<=32&&Array.isArray(house.completedActions)&&house.completedActions.length<=64&&Array.isArray(house.transactions)&&house.transactions.length<=64&&Number.isInteger(house.preparedServings)&&house.preparedServings>=0&&house.preparedServings<=32,'Invalid interior inventory/history');for(const action of house.actions)check(!!houseActionDefinition(action.type)&&Array.isArray(action.participants)&&action.participants.length>=1&&action.participants.length<=8&&action.participants.every(i=>Number.isInteger(i)&&(model.people.household[i]===h||personAtHouse(model,i,house))&&Number.isFinite(action.progress[i])&&action.progress[i]>=0&&action.progress[i]<=action.durationMinutes+1e-6)&&Number.isFinite(action.start)&&action.until===action.start+action.durationMinutes,'Invalid interior action');for(const action of house.actions)if(action.type==='cuddle'){const ids=action.participants.map(i=>`${model.prefix}-p${i}`);check(ids.length===2&&Array.isArray(action.consentingPersonIds)&&action.consentingPersonIds.length===2&&new Set(action.consentingPersonIds).size===2&&ids.every(id=>action.consentingPersonIds.includes(id))&&romanceAvailability(model,ids[0],ids[1],{mutualConsent:true}).available,'Invalid saved cuddle consent');}for(const action of house.actions)if(action.relationshipDecision!==undefined)check(action.type==='conversation'&&HOUSE_RELATIONSHIP_DECISIONS.some(d=>d.id===action.relationshipDecision&&action.durationMinutes>=d.durationMinutes)&&(!['askOnDate','propose','marry','startFamily'].includes(action.relationshipDecision)||action.relationshipIntent==='romantic'),'Invalid saved relationship decision');for(const action of house.actions)if(['propose','marry','separate','divorce','startFamily'].includes(action.relationshipDecision)){const ids=action.participants.map(i=>`${model.prefix}-p${i}`);check(ids.length===2&&Array.isArray(action.consentingPersonIds)&&action.consentingPersonIds.length===2&&new Set(action.consentingPersonIds).size===2&&ids.every(id=>action.consentingPersonIds.includes(id)),'Invalid saved commitment consent');}for(const action of house.actions)if(action.conversationChoice!==undefined)check(action.type==='conversation'&&HOUSE_CONVERSATION_CHOICES.some(c=>c.id===action.conversationChoice)&&(action.conversationChoice!=='flirt'||action.relationshipIntent==='romantic'),'Invalid saved conversation choice');for(const action of house.actions)if(action.relationshipIntent!==undefined){check(['conversation','cuddle'].includes(action.type)&&['friendly','romantic'].includes(action.relationshipIntent),'Invalid saved relationship intent');if(action.relationshipIntent==='romantic'){const ids=action.participants.map(i=>`${model.prefix}-p${i}`);check(Array.isArray(action.consentingPersonIds)&&action.consentingPersonIds.length===2&&new Set(action.consentingPersonIds).size===2&&ids.every(id=>action.consentingPersonIds.includes(id)),'Invalid saved romantic consent');check(romanceAvailability(model,ids[0],ids[1],{mutualConsent:true}).available,'Invalid saved romantic participants');}}for(const action of house.actions)if(action.seatIndices!==undefined){const target=actionObject(house,action);check(target?.type==='diningTable'&&Array.isArray(action.seatIndices)&&action.seatIndices.length===action.participants.length&&new Set(action.seatIndices).size===action.seatIndices.length&&action.seatIndices.every(seat=>Number.isInteger(seat)&&seat>=0&&seat<target.capacity),'Invalid retained dining seat reservation');}}for(const [key,active]of Object.entries(state.active)){const i=Number(key);check(Number.isInteger(i)&&i>=0&&i<model.people.age.length&&state.homes[active.household]?.actions.some(action=>action.id===active.actionId&&action.participants.includes(i)),'Invalid active interior resident');}}

export function releaseHouseVisitParticipant(model,i,minute,{reason='Visitor returning home'}={}){const visit=model.visits?.active?.[i];if(visit)cancelVisitingTasks(model,i,`${model.prefix}-h${visit.household}`,minute);const entry=activeEntry(model,i);if(!entry)return;const {house,action}=entry;for(const j of action.participants){interruptActiveHouseTask(model,j,action.id,minute,reason);delete model.houses.active[j];}house.actions=house.actions.filter(a=>a.id!==action.id);house.interruptedActions=[...(house.interruptedActions??[]),{actionId:action.id,type:action.type,minute,reason,actualPersonMinutes:Object.values(action.progress).reduce((a,b)=>a+b,0),noCompletionGranted:true}].slice(-64);recordEvent(model,'HOUSEHOLD_ACTION_INTERRUPTED',{minute,householdId:house.householdId,actionId:action.id,reason});}

export function cancelHouseholdAction(model,{householdId,personId,actionId}){const i=personIndex(model,personId),entry=activeEntry(model,i);check(entry&&entry.house.householdId===householdId&&entry.action.id===actionId,'The queued activity is no longer active');const {house,action}=entry;for(const j of action.participants)delete model.houses.active[j];house.actions=house.actions.filter(a=>a.id!==action.id);house.interruptedActions=[...(house.interruptedActions??[]),{actionId,type:action.type,minute:model.minute,reason:'Queued task cancelled',refund:0,noCompletionGranted:true,actualPersonMinutes:Object.values(action.progress).reduce((a,b)=>a+b,0)}].slice(-64);recordEvent(model,'HOUSEHOLD_ACTION_INTERRUPTED',{householdId,personId,actionId,reason:'Queued task cancelled',refund:0});}

export function getHouseState(model,id){return clone(houseFor(model,householdIndex(model,id)));}

function publishLifeEvents(model,home,previous){const rows=home.life?.events??[],at=previous?rows.indexOf(previous):-1;for(const {type,...detail}of rows.slice(at+1))if(type!=='activity-completed')recordEvent(model,'HOUSE_LIFE_'+type.toUpperCase().replaceAll('-','_'),{householdId:home.householdId,...detail});}
export function configureHouseLife(model,input){const {householdId,...patch}=input??{},h=householdIndex(model,householdId),home=getHouseState(model,h);check(Object.keys(model.houses?.homes??{}).length<128||model.houses?.homes?.[h],'At most 128 retained homes');const result=configureLife(model,home,patch);model.houses??={schemaVersion:HOUSE_VERSION,homes:{},active:{}};model.houses.homes[h]=home;return{...result,command:{tick:model.tick,minute:model.minute,kind:'house-life',request:clone(input)}};}

function progressionHomeForPerson(model,hostHouse,i){const owner=model.people.household[i],host=Number(hostHouse.householdId.slice((model.prefix+'-h').length));return owner===host?hostHouse:model.houses?.homes?.[owner]??houseFor(model,owner);}
export function houseActionObject(home,action){return actionObject(home,action);}

function roommateResidents(model,id){const h=householdIndex(model,id),p=model.people;return inspectHouseRoommates(model,id).map(row=>{const i=personIndex(model,row.id);return{...row,index:i,label:row.name,ageYears:p.ageYears[i],roommate:true,guest:false,role:'NPC roommate',canSendHome:false,atHome:roommateAtHouse(model,i,h),status:row.phase==='moving-out'?'Moving out':roommateAtHouse(model,i,h)?'At home':p.remaining[i]>0?'Travelling':p.activity[i]===1?'At work':'Away',householdId:row.financialHouseholdId,currentActivity:ACTIVITIES[p.activity[i]]};});}

export function houseActionDefinition(type){return HOUSE_ACTIONS[type]??systemActionDefinition(type);}
function itemActionDefinition(type){return ITEM_ACTIONS[type]??systemActionDefinition(type);}

export function applyHouseholdAction(model,input){const draft=projectSystemNeedInterruption(model,input);if(!draft)return applyPlannedHouseholdAction(model,input);const result=applyPlannedHouseholdAction(draft,input);if(model.houseTasks&&draft.houseTasks)draft.houseTasks=retainTaskReferences(model.houseTasks,draft.houseTasks);Object.assign(model,draft);return result;}

// Queue processing can hold references across admission. Preserve those references when committing a date-interruption draft.
function retainTaskReferences(target,source){if(Array.isArray(source)){const previous=[...target];target.splice(0,target.length,...source.map((item,index)=>{const old=item?.id?previous.find(row=>row?.id===item.id):previous[index];return old&&item&&typeof item==='object'?retainTaskReferences(old,item):item;}));return target;}for(const key of Object.keys(target))if(!Object.hasOwn(source,key))delete target[key];for(const [key,value]of Object.entries(source)){if(value&&typeof value==='object'&&target[key]&&typeof target[key]==='object'&&Array.isArray(value)===Array.isArray(target[key]))retainTaskReferences(target[key],value);else target[key]=value;}return target;}
